class ErrorBoundary{constructor(moduleName){this.moduleName=moduleName;this.errors=[];}wrap(fn){return(...args)=>{try{return fn(...args);}catch(error){this.handleError(error);return null;}};}async wrapAsync(fn){return async(...args)=>{try{return await fn(...args);}catch(error){this.handleError(error);return null;}};}handleError(error){console.error(`[${this.moduleName}] Error:`,error);if(window.AppLogger){window.AppLogger.error({module:this.moduleName,error:error.message,stack:error.stack});}this.errors.push({timestamp:new Date(),error:error.message,stack:error.stack});this.showUserMessage();}showUserMessage(){if(sessionStorage.getItem(`error_shown_${this.moduleName}`)){return;}const message=`We encountered an issue with ${this.moduleName}. Please refresh the page.`;if(window.showToast){window.showToast(message,'error');}else{console.warn(message);}sessionStorage.setItem(`error_shown_${this.moduleName}`,'true');}getErrors(){return this.errors;}}if(typeof module !=='undefined' && module.exports){module.exports=ErrorBoundary;}else{window.ErrorBoundary=ErrorBoundary;}